description:
[
  {
    "topic": "Immediate US release verification: official agencies and Forex Factory USD calendar",
    "why_gold_cares": "The snapshot arrives just after a standard US release window; a fresh surprise could explain the gold rise and softer dollar.",
    "impact_threshold": "A material actual-versus-consensus surprise, significant revision, or unexpected release delay that reprices the Fed path; first verify which releases are scheduled.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Federal Reserve calendar, policy decision, statement and press conference",
    "why_gold_cares": "Unexpected policy guidance changes expected rates, real yields and the dollar; verify today's official schedule rather than assume an announcement.",
    "impact_threshold": "A departure from priced policy expectations or a substantive change in guidance, inflation assessment or balance-sheet policy.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Fresh CPI, PCE and employment information",
    "why_gold_cares": "Inflation and labor surprises alter the expected policy path; cooler inflation or weaker employment can support gold through lower yields.",
    "impact_threshold": "An unexpected release or substantial surprise in policy-sensitive components, corroborated by rates repricing rather than the headline alone.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Live TIPS real yields, Treasury yields, DXY and rate futures",
    "why_gold_cares": "Lower real yields reduce gold's opportunity cost and dollar weakness supports its dollar price; unchanged daily yield series may conceal intraday moves.",
    "impact_threshold": "A sharp, sustained cross-market move confirmed by timestamped live pricing and a clear catalyst, not a stale daily observation.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Treasury auction results and financing announcements",
    "why_gold_cares": "Demand and supply surprises can reprice yields and the dollar, reinforcing or reversing gold's short-term move.",
    "impact_threshold": "A pronounced auction tail or stop-through, unusual bidder composition, or unexpected financing guidance that moves Treasury prices.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical escalation, sanctions and verified ceasefire developments",
    "why_gold_cares": "Escalation can increase safe-haven demand; credible de-escalation can unwind it, while energy shocks complicate the rates response.",
    "impact_threshold": "Verified developments materially changing conflict scope, energy supply, major-power involvement or the durability of a ceasefire.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Banking stress, credit disruption and emergency official support",
    "why_gold_cares": "Financial stress can support safe-haven demand and easing expectations, but urgent cash raising can initially pressure gold.",
    "impact_threshold": "Confirmed institutional distress, emergency funding action or broad credit deterioration with visible market transmission.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Treasury cash rebuilding, repo conditions and reserve liquidity",
    "why_gold_cares": "The supplied Treasury cash increase warrants checking funding conditions, but cash balances alone do not establish an intraday gold catalyst.",
    "impact_threshold": "Unexpected funding dislocation or official liquidity intervention corroborated by repo, dollar funding or broader risk-market stress.",
    "directional_risk": "TWO_WAY"
  }
]
